examples.source:
packetdiag {
  colwidth = 32;
  node_height = 40;
  0-15: Source Port;
  16-31: Destination Port;
  32-63: Sequence Number;
  64-95: Acknowledgment Number;
  96-99: Offset [rotate = 270];
  100-105: Reserved;
  106-111: Flags [color = "#ffcccc"];
  112-127: Window;
}

packetdiag {
  colwidth = 8;
  0: URG;
  1: ACK;
  2: PSH;
  3: RST;
  4: SYN;
  5: FIN;
  6-7: Spare [color = "#dddddd"];
}

packetdiag {
  colwidth = 16;
  0-7: Type;
  8-15: Code;
  16-31: Checksum [height = 60];
  48-63: Payload;
}

packetdiag {
  scale_direction = rtl;
  0-3: Version;
  4-7: IHL;
  8-15: ToS;
  16-31: "Total Length";
}
